//! Boxed In minigame, a cat's take on sokoban. Push every box onto a target.
//! Boxes can only be pushed, never pulled, so a box in a corner is stuck.
//!
//! Levels are generated by playing backwards: boxes start on their targets
//! and the cat pulls them away. Every pull is a push in reverse, so each
//! level can be solved. Levels add boxes and room as they go.
//!
//! The 18x9 board at 7px pitch fills the 128x64 screen, one sprite per cell.

use core::fmt::Write as _;

use embedded_graphics::prelude::{Point, Size};
use heapless::{String, Vec};
#[cfg(not(feature = "desktop"))]
use micromath::F32Ext;
use crate::t;

use crate::{
    assets::plants::{GRASS_GROWING, GRASS_SEEDLING, GRASS_YOUNG},
    context::{GameContext, StatId},
    input::{Button, Buttons},
    rand::xorshift32,
    render::{Renderer, Sprite, SpriteOpts},
    scene::{Scene, SceneId},
    ui::menu::{Menu, MenuItem, MenuResult},
    ui::popup::Popup,
};

const COLS: usize = 18;
const ROWS: usize = 9;
const CELLS: usize = COLS * ROWS;

const PITCH: i32 = 7;
const CELL_IN: u32 = (PITCH - 1) as u32;

// 7x7 sprites, one byte per row.
const CAT: &[u8] = b"\x82\xc6\xfe\xd6\xd6\x7c\x38";
const BOX: &[u8] = b"\x38\x6c\xc6\x82\xc6\x6c\x38";
const BOX_ON_TARGET: &[u8] = b"\x7c\x82\xba\xaa\xba\x82\x7c";
const TARGET: &[u8] = b"\x00\x6c\x44\x00\x44\x6c\x00";

// Directions, in `Button` order.
const UP: u8 = 0;
const DOWN: u8 = 1;
const LEFT: u8 = 2;
const RIGHT: u8 = 3;

const MAX_BOXES: usize = 5;
const MAX_PULLS: usize = 256;
/// Rooms carved per level, and backward games played in each.
const ROOMS: usize = 4;
const RUNS_PER_ROOM: usize = 5;
/// More runs once scoring looks for tricky boards, so it has more to pick from.
const HARD_RUNS_PER_ROOM: usize = 8;
/// Level from which wall islands break up the open floor.
const ISLANDS_FROM: u32 = 6;
const MAX_ISLANDS: usize = 5;
/// Level from which boards are scored for how tricky they are.
const HARD_FROM: u32 = 13;
/// Level from which the board is split into separate areas that boxes
/// bridge between.
const MULTI_FROM: u32 = 16;
/// Most wall cells a bridge between areas will cut through.
const MAX_BRIDGE: usize = 5;
/// Give up on this many boxes after this many rooms without a good run.
const MAX_ROOMS: usize = 24;
/// Moves remembered for undo.
const HISTORY: usize = 128;

/// Grass tufts dotted around outside the room, small enough to fit the gaps.
const GRASS_SPRITES: &[&Sprite] = &[&GRASS_SEEDLING, &GRASS_YOUNG, &GRASS_GROWING];
const MAX_GRASS: usize = 10;
/// Dirt specks scattered over the floor.
const MAX_DIRT: usize = 48;

const WIN_RESET_DELAY: f32 = 2.5;
const INTRO_TIME: f32 = 1.2;

#[derive(Clone, Copy, PartialEq, Eq)]
enum State {
    /// "Level n" over the fresh board.
    Intro,
    Playing,
    Win,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum BoxedInAction {
    Retry,
    NewBoard,
}

const OPTIONS_ITEMS: &[MenuItem<BoxedInAction>] = &[
    MenuItem { label: t!("Retry"),     icon: None, submenu: None, action: Some(BoxedInAction::Retry),    confirm: None, confirm_on_vacation: None },
    MenuItem { label: t!("New Board"), icon: None, submenu: None, action: Some(BoxedInAction::NewBoard), confirm: None, confirm_on_vacation: None },
];

/// (boxes, floor cells, backward pulls) for a level (1-based).
fn level_params(level: u32) -> (usize, usize, usize) {
    match level {
        0 | 1 => (1, 24, 8),
        2 => (1, 30, 10),
        3 => (2, 34, 16),
        4 => (2, 38, 18),
        5 => (3, 42, 24),
        6 => (3, 46, 26),
        7 => (4, 50, 32),
        8 => (4, 54, 34),
        9 => (5, 56, 40),
        10 => (5, 60, 42),
        11..=15 => (5, 64, 45),
        // Split over areas, with bridges to cross.
        _ => (5, 66, 60),
    }
}

/// The cell one step from `i` in direction `d`, if it's on the board.
fn step(i: usize, d: u8) -> Option<usize> {
    let (r, c) = (i / COLS, i % COLS);
    match d {
        UP if r > 0 => Some(i - COLS),
        DOWN if r < ROWS - 1 => Some(i + COLS),
        LEFT if c > 0 => Some(i - 1),
        RIGHT if c < COLS - 1 => Some(i + 1),
        _ => None,
    }
}

fn opposite(d: u8) -> u8 {
    d ^ 1
}

fn rand_below(rng: &mut u32, n: usize) -> usize {
    (xorshift32(rng) as usize) % n
}

#[derive(Clone, Copy)]
struct Level {
    wall: [bool; CELLS],
    target: [bool; CELLS],
    boxes: [bool; CELLS],
    player: usize,
}

impl Level {
    const fn new() -> Self {
        Self {
            wall: [true; CELLS],
            target: [false; CELLS],
            boxes: [false; CELLS],
            player: 0,
        }
    }

    fn free(&self, i: usize) -> bool {
        !self.wall[i] && !self.boxes[i]
    }

    /// Walk the cat one cell, pushing a box if one is in the way. Returns
    /// whether a box was pushed, or `None` if the cat couldn't move.
    fn try_move(&mut self, d: u8) -> Option<bool> {
        let next = step(self.player, d)?;
        if self.wall[next] {
            return None;
        }
        if !self.boxes[next] {
            self.player = next;
            return Some(false);
        }
        let beyond = step(next, d)?;
        if !self.free(beyond) {
            return None;
        }
        self.boxes[next] = false;
        self.boxes[beyond] = true;
        self.player = next;
        Some(true)
    }

    /// Take back a move made in direction `d`.
    fn undo(&mut self, d: u8, pushed: bool) {
        let here = self.player;
        let Some(back) = step(here, opposite(d)) else { return };
        if pushed {
            if let Some(b) = step(here, d) {
                self.boxes[b] = false;
                self.boxes[here] = true;
            }
        }
        self.player = back;
    }

    fn solved(&self) -> bool {
        (0..CELLS).all(|i| !self.boxes[i] || self.target[i])
    }

    /// Cells the cat can walk to without pushing anything.
    fn reachable(&self, from: usize) -> [bool; CELLS] {
        let mut seen = [false; CELLS];
        let mut stack = [0u8; CELLS];
        let mut top = 1;
        stack[0] = from as u8;
        seen[from] = true;
        while top > 0 {
            top -= 1;
            let i = stack[top] as usize;
            for d in 0..4 {
                if let Some(j) = step(i, d) {
                    if !seen[j] && self.free(j) {
                        seen[j] = true;
                        stack[top] = j as u8;
                        top += 1;
                    }
                }
            }
        }
        seen
    }

    /// Top-left pixel of cell 0 that centres the drawn walls on screen.
    fn origin(&self) -> Point {
        let (mut r0, mut c0, mut r1, mut c1) = (ROWS, COLS, 0, 0);
        for i in (0..CELLS).filter(|&i| !self.wall[i]) {
            let (r, c) = (i / COLS, i % COLS);
            r0 = r0.min(r);
            c0 = c0.min(c);
            r1 = r1.max(r);
            c1 = c1.max(c);
        }
        // Walls ring the floor, and the last one drawn leaves a 1px gap.
        let w = (c1 - c0 + 3) as i32 * PITCH - 1;
        let h = (r1 - r0 + 3) as i32 * PITCH - 1;
        Point::new(
            (128 - w) / 2 - (c0 as i32 - 1) * PITCH,
            (64 - h) / 2 - (r0 as i32 - 1) * PITCH,
        )
    }

    /// Wall cells touching the floor, including diagonally.
    fn visible_wall(&self, i: usize) -> bool {
        let (r, c) = ((i / COLS) as i32, (i % COLS) as i32);
        (-1..=1).any(|dr| {
            (-1..=1).any(|dc| {
                let (rr, cc) = (r + dr, c + dc);
                rr >= 0 && cc >= 0 && rr < ROWS as i32 && cc < COLS as i32
                    && !self.wall[(rr * COLS as i32 + cc) as usize]
            })
        })
    }
}

/// A backward pull: the cat at `from` stepped in `dir`, dragging the box
/// behind it. Forwards, that's a push from `from + dir` towards `-dir`.
type Pull = (u8, u8);

/// Inclusive rows and columns that a room may be carved in.
#[derive(Clone, Copy)]
struct Zone {
    r0: usize,
    c0: usize,
    r1: usize,
    c1: usize,
}

/// Everything inside the outer ring of wall.
const INTERIOR: Zone = Zone { r0: 1, c0: 1, r1: ROWS - 2, c1: COLS - 2 };

/// Carve a single room over the whole board. Every floor cell is area 1.
fn carve_room(level: &mut Level, area: &mut [u8; CELLS], floor: usize, rng: &mut u32) {
    *level = Level::new();
    *area = [0; CELLS];
    carve_zone(level, area, INTERIOR, floor, 1, rng);
}

/// Carve 2-3 rooms with wall between them, and return how many. Boxes cut
/// bridges across the gaps in `scramble`.
fn carve_areas(level: &mut Level, area: &mut [u8; CELLS], floor: usize, rng: &mut u32) -> u8 {
    *level = Level::new();
    *area = [0; CELLS];
    let (r1, c1) = (INTERIOR.r1, INTERIOR.c1);
    let mut zones: Vec<Zone, 3> = Vec::new();
    match rand_below(rng, 4) {
        // Side by side.
        0 => {
            let s = 6 + rand_below(rng, 4);
            let gap = 1 + rand_below(rng, 3);
            let _ = zones.push(Zone { r0: 1, c0: 1, r1, c1: s });
            let _ = zones.push(Zone { r0: 1, c0: s + gap + 1, r1, c1 });
        }
        // One above the other, overlapping partway.
        1 => {
            let _ = zones.push(Zone { r0: 1, c0: 1, r1: 3, c1: 10 + rand_below(rng, 3) });
            let _ = zones.push(Zone { r0: 5, c0: 5 + rand_below(rng, 3), r1, c1 });
        }
        // Three in a row.
        2 => {
            let (g1, g2) = (1 + rand_below(rng, 2), 1 + rand_below(rng, 2));
            let w = (c1 - g1 - g2) / 3;
            let b0 = 1 + w + g1;
            let _ = zones.push(Zone { r0: 1, c0: 1, r1, c1: w });
            let _ = zones.push(Zone { r0: 1, c0: b0, r1, c1: b0 + w - 1 });
            let _ = zones.push(Zone { r0: 1, c0: b0 + w + g2, r1, c1 });
        }
        // A tall room beside two short ones.
        _ => {
            let s = 5 + rand_below(rng, 4);
            let c0 = s + 2 + rand_below(rng, 2);
            let _ = zones.push(Zone { r0: 1, c0: 1, r1, c1: s });
            let _ = zones.push(Zone { r0: 1, c0, r1: 3, c1 });
            let _ = zones.push(Zone { r0: 5, c0, r1, c1 });
        }
    }
    let each = floor / zones.len();
    for (n, &z) in zones.iter().enumerate() {
        carve_zone(level, area, z, each, n as u8 + 1, rng);
    }
    zones.len() as u8
}

/// Carve a connected room of about `floor` cells inside `zone` by stamping
/// small rectangles over cells that are already floor, tagging them `id`.
fn carve_zone(level: &mut Level, area: &mut [u8; CELLS], zone: Zone, floor: usize, id: u8, rng: &mut u32) {
    let (rows, cols) = (zone.r1 - zone.r0 + 1, zone.c1 - zone.c0 + 1);
    // Leave some of a small zone uncarved, so it isn't one solid block.
    let floor = floor.min(rows * cols * 3 / 4);
    let random_cell = |rng: &mut u32| {
        (zone.r0 + rand_below(rng, rows)) * COLS + zone.c0 + rand_below(rng, cols)
    };
    let mut count = 0;
    let mut anchor = random_cell(rng);
    while count < floor {
        let (ar, ac) = (anchor / COLS, anchor % COLS);
        let w = (2 + rand_below(rng, 2)).min(cols);
        let h = (2 + rand_below(rng, 2)).min(rows);
        let c0 = ac.saturating_sub(rand_below(rng, w)).clamp(zone.c0, zone.c1 + 1 - w);
        let r0 = ar.saturating_sub(rand_below(rng, h)).clamp(zone.r0, zone.r1 + 1 - h);
        for r in r0..r0 + h {
            for c in c0..c0 + w {
                let i = r * COLS + c;
                if level.wall[i] {
                    level.wall[i] = false;
                    area[i] = id;
                    count += 1;
                }
            }
        }
        // Next stamp grows from a random floor cell of this room.
        loop {
            anchor = random_cell(rng);
            if !level.wall[anchor] {
                break;
            }
        }
    }
}

/// Wall islands for a level: none early on, then a few more every other level.
fn islands(level: u32) -> usize {
    if level < ISLANDS_FROM {
        0
    } else {
        (2 + (level - ISLANDS_FROM) as usize / 2).min(MAX_ISLANDS)
    }
}

/// Drop 1x1 and 1x2 walls into open floor. Each one has floor all around it,
/// so it can't split the room.
fn add_islands(level: &mut Level, count: usize, rng: &mut u32) {
    let mut placed = 0;
    for _ in 0..count * 20 {
        if placed == count {
            break;
        }
        let a = random_free(level, rng);
        let b = if rand_below(rng, 2) == 0 {
            step(a, rand_below(rng, 4) as u8).filter(|&b| !level.wall[b])
        } else {
            None
        };
        let island = |i: usize| i == a || Some(i) == b;
        let open = [Some(a), b].into_iter().flatten().all(|i| {
            let (r, c) = ((i / COLS) as i32, (i % COLS) as i32);
            (-1..=1).all(|dr| {
                (-1..=1).all(|dc| {
                    let j = ((r + dr) * COLS as i32 + c + dc) as usize;
                    island(j) || !level.wall[j]
                })
            })
        });
        if open {
            level.wall[a] = true;
            if let Some(b) = b {
                level.wall[b] = true;
            }
            placed += 1;
        }
    }
}

fn random_free(level: &Level, rng: &mut u32) -> usize {
    loop {
        let i = rand_below(rng, CELLS);
        if level.free(i) {
            return i;
        }
    }
}

fn pair_bit(a: u8, b: u8) -> u16 {
    (1 << (a * 4 + b)) | (1 << (b * 4 + a))
}

/// How many wall cells to cut so box `b` can be pulled in direction `d`
/// into an area the cat can reach, if it can be at all. The run must be
/// straight, stay off the outer ring, and join two areas not yet bridged.
fn bridge(level: &Level, area: &[u8; CELLS], reach: &[bool; CELLS], bridged: u16, b: usize, d: u8) -> Option<usize> {
    if area[b] == 0 {
        return None;
    }
    let mut i = b;
    for cut in 1..=MAX_BRIDGE + 1 {
        i = step(i, d)?;
        let (r, c) = (i / COLS, i % COLS);
        if r == 0 || c == 0 || r == ROWS - 1 || c == COLS - 1 {
            return None;
        }
        if !level.wall[i] {
            let other = area[i];
            let ok = cut > 1 && reach[i] && other != 0 && other != area[b]
                && bridged & pair_bit(area[b], other) == 0;
            return ok.then_some(cut - 1);
        }
    }
    None
}

/// Play backwards from a solved room. Returns the most scrambled state seen
/// with every box off its target, its score, and the pulls that led there.
///
/// A box never crosses its own trail, so it can't wander back and forth over
/// the whole room, but it's drawn to cells other boxes have crossed. Those
/// shared lanes become the squeezes once `trim` walls off the rest.
///
/// The cat starts in one area. A box in another area facing the cat's side
/// across a short run of wall gets a bridge cut through it, and is dragged
/// across. Each pair of areas gets one bridge, so it's a chokepoint.
fn scramble(
    solved: &Level,
    area: &[u8; CELLS],
    pulls: usize,
    hard: bool,
    rng: &mut u32,
) -> Option<(Level, u32, Vec<Pull, MAX_PULLS>)> {
    let mut level = *solved;
    level.player = random_free(&level, rng);
    let mut path: Vec<Pull, MAX_PULLS> = Vec::new();
    let mut best: Option<(Level, u32, usize)> = None;
    // Which box sits on each cell, and a bit per box for cells it has been on.
    let mut id = [u8::MAX; CELLS];
    let mut trail = [0u8; CELLS];
    let mut n = 0;
    for i in (0..CELLS).filter(|&i| level.boxes[i]) {
        id[i] = n;
        trail[i] = 1 << n;
        n += 1;
    }
    // Score bits: how often the pulled box or direction changed, and how
    // often a box followed another's trail.
    let mut last: Option<(usize, u8)> = None;
    let mut switches = 0u32;
    let mut turns = 0u32;
    let mut shared = 0u32;
    // Hard scoring: boxes pushed against each other or down 1-wide lanes,
    // and boxes cutting the cat off from part of the room.
    let mut contact = 0u32;
    let mut narrow = 0u32;
    let mut split = 0u32;
    // A bit per pair of areas already bridged.
    let mut bridged = 0u16;

    for _ in 0..pulls.min(MAX_PULLS) {
        let reach = level.reachable(level.player);
        if hard {
            let cut = (0..CELLS).any(|i| level.free(i) && !reach[i]);
            split += cut as u32;
        }
        // Each box has at most four sides to pull from.
        // (cell pulled to, direction, weight, wall cells to cut first)
        let mut options: Vec<(usize, u8, u32, usize), { MAX_BOXES * 4 }> = Vec::new();
        let mut total = 0;
        for b in 0..CELLS {
            if !level.boxes[b] {
                continue;
            }
            let mine = 1u8 << id[b];
            for d in 0..4 {
                let Some(p) = step(b, d) else { continue };
                if level.wall[p] {
                    if let Some(cut) = bridge(&level, area, &reach, bridged, b, d) {
                        total += 6;
                        let _ = options.push((p, d, 6, cut));
                    }
                    continue;
                }
                let Some(q) = step(p, d) else { continue };
                if reach[p] && level.free(q) && trail[p] & mine == 0 {
                    // Favour longer pushes and other boxes' lanes.
                    let mut weight = 1;
                    if last == Some((b, d)) {
                        weight += 8;
                    }
                    if trail[p] != 0 {
                        weight += 3;
                    }
                    total += weight;
                    let _ = options.push((p, d, weight, 0));
                }
            }
        }
        if options.is_empty() {
            break;
        }
        let mut pick = rand_below(rng, total as usize) as u32;
        let &(p, d, _, cut) = options
            .iter()
            .find(|o| {
                if pick < o.2 {
                    true
                } else {
                    pick -= o.2;
                    false
                }
            })
            .unwrap_or(&options[0]);
        let b = step(p, opposite(d)).unwrap_or(p);
        if cut > 0 {
            let mut i = b;
            for _ in 0..cut {
                i = step(i, d).unwrap_or(i);
                level.wall[i] = false;
            }
            let far = step(i, d).unwrap_or(i);
            bridged |= pair_bit(area[b], area[far]);
        }
        if let Some((lb, ld)) = last {
            if lb != b {
                switches += 1;
            } else if ld != d {
                turns += 1;
            }
        }
        if trail[p] != 0 {
            shared += 1;
        }
        if hard {
            let side = |i: usize, s: u8| step(i, s).map_or(true, |j| level.wall[j]);
            let (s1, s2) = if d < LEFT { (LEFT, RIGHT) } else { (UP, DOWN) };
            narrow += (side(p, s1) && side(p, s2)) as u32;
            let touching = (0..4).any(|s| step(p, s).map_or(false, |j| j != b && level.boxes[j]));
            contact += touching as u32;
        }
        level.boxes[b] = false;
        level.boxes[p] = true;
        id[p] = id[b];
        id[b] = u8::MAX;
        trail[p] |= 1 << id[p];
        level.player = step(p, d).unwrap_or(p);
        last = Some((p, d));
        let _ = path.push((p as u8, d));

        if (0..CELLS).all(|i| !(level.boxes[i] && level.target[i])) {
            let mut score = displacement(&level) * 2 + switches * 3 + turns + shared * 2;
            if hard {
                score += contact * 3 + narrow * 3 + split * 2;
            }
            if best.map_or(true, |(_, s, _)| score > s) {
                best = Some((level, score, path.len()));
            }
        }
    }

    best.map(|(level, score, len)| {
        path.truncate(len);
        (level, score, path)
    })
}

/// Sum over boxes of the distance to the nearest target.
fn displacement(level: &Level) -> u32 {
    let mut total = 0;
    for b in (0..CELLS).filter(|&i| level.boxes[i]) {
        let (br, bc) = ((b / COLS) as i32, (b % COLS) as i32);
        total += (0..CELLS)
            .filter(|&t| level.target[t])
            .map(|t| ((t / COLS) as i32 - br).abs() + ((t % COLS) as i32 - bc).abs())
            .min()
            .unwrap_or(0) as u32;
    }
    total
}

/// Gather the targets near each other, so boxes leaving them share exits.
/// With several areas, they're shared out between them.
fn place_targets(level: &mut Level, area: &[u8; CELLS], areas: u8, boxes: usize, rng: &mut u32) {
    for n in 0..boxes {
        let id = (n % areas as usize) as u8 + 1;
        let mut near: Vec<u8, CELLS> = Vec::new();
        let mut any: Vec<u8, CELLS> = Vec::new();
        for i in (0..CELLS).filter(|&i| level.free(i) && area[i] == id) {
            let (r, c) = ((i / COLS) as i32, (i % COLS) as i32);
            let close = (0..CELLS).filter(|&t| level.target[t] && area[t] == id).any(|t| {
                ((t / COLS) as i32 - r).abs() <= 2 && ((t % COLS) as i32 - c).abs() <= 2
            });
            if close {
                let _ = near.push(i as u8);
            }
            let _ = any.push(i as u8);
        }
        let pool = if near.is_empty() { &any } else { &near };
        let t = if pool.is_empty() {
            random_free(level, rng)
        } else {
            pool[rand_below(rng, pool.len())] as usize
        };
        level.target[t] = true;
        level.boxes[t] = true;
    }
}

/// Directions for the cat to walk from `from` to `to` without pushing.
/// Steps onto `lanes` cells cost less, so walks bunch up along them.
fn walk(level: &Level, from: usize, to: usize, lanes: &[bool; CELLS]) -> Option<Vec<u8, CELLS>> {
    const OPEN: u16 = u16::MAX;
    let mut dist = [OPEN; CELLS];
    let mut prev = [0u8; CELLS];
    let mut done = [false; CELLS];
    dist[from] = 0;
    loop {
        // Plain Dijkstra: the board is small enough to scan for the nearest.
        let mut i = CELLS;
        for j in 0..CELLS {
            if !done[j] && dist[j] != OPEN && (i == CELLS || dist[j] < dist[i]) {
                i = j;
            }
        }
        if i == CELLS {
            return None;
        }
        if i == to {
            break;
        }
        done[i] = true;
        for d in 0..4 {
            if let Some(j) = step(i, d) {
                let cost = dist[i] + if lanes[j] { 1 } else { 3 };
                if level.free(j) && cost < dist[j] {
                    dist[j] = cost;
                    prev[j] = d;
                }
            }
        }
    }
    let mut dirs: Vec<u8, CELLS> = Vec::new();
    let mut at = to;
    while at != from {
        let d = prev[at];
        let _ = dirs.push(d);
        at = step(at, opposite(d))?;
    }
    dirs.reverse();
    Some(dirs)
}

/// Wall over every floor cell the solution never touches. Replays the pulls
/// forwards as pushes with the cheapest walk between them, so what's left
/// is the space the solution needs, which still holds the solution. A second
/// replay routes the walks along the first one's lanes, freeing up more.
fn trim(level: &mut Level, pulls: &[Pull]) {
    let mut used = [false; CELLS];
    for _ in 0..2 {
        let Some(lanes) = solution_cells(level, pulls, &used) else { return };
        used = lanes;
    }
    for i in 0..CELLS {
        if !used[i] {
            level.wall[i] = true;
        }
    }
}

/// Every cell the cat or a box covers while solving with `pulls`.
fn solution_cells(level: &Level, pulls: &[Pull], lanes: &[bool; CELLS]) -> Option<[bool; CELLS]> {
    let mut used = [false; CELLS];
    let mut sim = *level;
    used[sim.player] = true;
    for i in (0..CELLS).filter(|&i| sim.boxes[i]) {
        used[i] = true;
    }
    for &(p, d) in pulls.iter().rev() {
        let stand = step(p as usize, d)?;
        let path = walk(&sim, sim.player, stand, lanes)?;
        for m in path.into_iter().chain(core::iter::once(opposite(d))) {
            sim.try_move(m)?;
            used[sim.player] = true;
            if let Some(b) = step(sim.player, m) {
                if sim.boxes[b] {
                    used[b] = true;
                }
            }
        }
    }
    Some(used)
}

/// A solvable level for `level_num`, with the backward pulls that made it.
fn generate(level_num: u32, rng: &mut u32) -> (Level, Vec<Pull, MAX_PULLS>) {
    let (mut boxes, floor, pulls) = level_params(level_num);
    let hard = level_num >= HARD_FROM;
    let runs = if hard { HARD_RUNS_PER_ROOM } else { RUNS_PER_ROOM };
    loop {
        let mut best: Option<(Level, u32, Vec<Pull, MAX_PULLS>)> = None;
        for room in 0..MAX_ROOMS {
            if room >= ROOMS && best.is_some() {
                break;
            }
            let mut solved = Level::new();
            let mut area = [0u8; CELLS];
            let areas = if level_num >= MULTI_FROM {
                carve_areas(&mut solved, &mut area, floor, rng)
            } else {
                carve_room(&mut solved, &mut area, floor, rng);
                1
            };
            add_islands(&mut solved, islands(level_num), rng);
            place_targets(&mut solved, &area, areas, boxes, rng);
            for _ in 0..runs {
                if let Some(run) = scramble(&solved, &area, pulls, hard, rng) {
                    if best.as_ref().map_or(true, |b| run.1 > b.1) {
                        best = Some(run);
                    }
                }
            }
        }
        if let Some((mut level, _, path)) = best {
            trim(&mut level, &path);
            return (level, path);
        }
        // Rooms this cramped won't come apart, so try with fewer boxes.
        boxes = boxes.saturating_sub(1).max(1);
    }
}

/// Decoration around and inside a room, rolled with each new board.
struct Scenery {
    /// Top-left and sprite index of each grass tuft.
    grass: Vec<(i16, i16, u8), MAX_GRASS>,
    dirt: Vec<(u8, u8), MAX_DIRT>,
}

impl Scenery {
    const fn new() -> Self {
        Self { grass: Vec::new(), dirt: Vec::new() }
    }

    fn roll(&mut self, level: &Level, origin: Point, rng: &mut u32) {
        self.grass.clear();
        self.dirt.clear();
        // The cell under a screen pixel, if it's on the board.
        let cell_at = |x: i32, y: i32| {
            let (c, r) = ((x - origin.x).div_euclid(PITCH), (y - origin.y).div_euclid(PITCH));
            (c >= 0 && r >= 0 && c < COLS as i32 && r < ROWS as i32)
                .then(|| r as usize * COLS + c as usize)
        };
        let in_room = |i: usize| !level.wall[i] || level.visible_wall(i);

        // Grass anywhere it clears the room, with a pixel to spare.
        let want = 6 + rand_below(rng, 5);
        for _ in 0..want * 10 {
            if self.grass.len() == want {
                break;
            }
            let v = rand_below(rng, GRASS_SPRITES.len());
            let (w, h) = (GRASS_SPRITES[v].width as i32, GRASS_SPRITES[v].height as i32);
            let x = rand_below(rng, (128 - w) as usize + 1) as i32;
            let y = rand_below(rng, (64 - h) as usize + 1) as i32;
            let hits_room = (x - 1..x + w + 1).any(|px| {
                (y - 1..y + h + 1).any(|py| cell_at(px, py).map_or(false, in_room))
            });
            let hits_grass = self.grass.iter().any(|&(gx, gy, gv)| {
                let g = GRASS_SPRITES[gv as usize];
                let (gx, gy) = (gx as i32, gy as i32);
                x < gx + g.width as i32 + 1 && gx < x + w + 1
                    && y < gy + g.height as i32 + 1 && gy < y + h + 1
            });
            if !hits_room && !hits_grass {
                let _ = self.grass.push((x as i16, y as i16, v as u8));
            }
        }

        // Dirt in small clumps on the floor, like Snake's.
        for _ in 0..3 + rand_below(rng, 4) {
            let centre = random_free(level, rng);
            let cx = origin.x + (centre % COLS) as i32 * PITCH + PITCH / 2;
            let cy = origin.y + (centre / COLS) as i32 * PITCH + PITCH / 2;
            let specks = 2 + rand_below(rng, 4);
            let mut placed = 0;
            for _ in 0..20 {
                if placed == specks {
                    break;
                }
                let x = cx + rand_below(rng, 9) as i32 - 4;
                let y = cy + rand_below(rng, 9) as i32 - 4;
                if !(0..128).contains(&x) || !(0..64).contains(&y) {
                    continue;
                }
                let on_floor = cell_at(x, y).map_or(false, |i| !level.wall[i]);
                let crowded = self.dirt.iter().any(|&(dx, dy)| {
                    (x - dx as i32).abs() <= 2 && (y - dy as i32).abs() <= 2
                });
                if on_floor && !crowded {
                    if self.dirt.push((x as u8, y as u8)).is_err() {
                        return;
                    }
                    placed += 1;
                }
            }
        }
    }
}

pub struct BoxedInScene {
    popup: Popup,
    intro_popup: Popup,

    level: Level,
    /// The level as generated, for Retry.
    start: Level,
    /// Where cell 0 is drawn, so the room sits centred.
    origin: Point,
    scenery: Scenery,
    level_num: u32,
    state: State,
    timer: f32,

    /// Ring of moves for undo: direction in the low bits, bit 2 if pushed.
    history: [u8; HISTORY],
    history_head: usize,
    history_len: usize,

    session_levels: u32,
    session_coins: i32,

    options_menu: Menu<BoxedInAction>,
    menu_active: bool,
}

impl BoxedInScene {
    pub fn new() -> Self {
        Self {
            popup: Popup::new(10, 14, 108, 36),
            intro_popup: Popup::new(24, 22, 80, 18),

            level: Level::new(),
            start: Level::new(),
            origin: Point::zero(),
            scenery: Scenery::new(),
            level_num: 1,
            state: State::Intro,
            timer: 0.0,

            history: [0; HISTORY],
            history_head: 0,
            history_len: 0,

            session_levels: 0,
            session_coins: 0,

            options_menu: Menu::new(OPTIONS_ITEMS),
            menu_active: false,
        }
    }

    fn new_board(&mut self, ctx: &mut GameContext) {
        let mut rng = ctx.rng;
        let (level, _) = generate(self.level_num, &mut rng);
        self.start = level;
        self.origin = level.origin();
        self.scenery.roll(&level, self.origin, &mut rng);
        ctx.rng = rng;
        self.retry();
        self.state = State::Intro;

        let mut n: String<8> = String::new();
        let _ = write!(n, "{}", self.level_num);
        let mut text: String<24> = String::new();
        crate::i18n::substitute(&mut text, t!("Level {n}"), &[("n", n.as_str())]);
        self.intro_popup.set_text(&text, false, true);
    }

    fn retry(&mut self) {
        self.level = self.start;
        self.history_len = 0;
        self.state = State::Playing;
        self.timer = 0.0;
    }

    fn record(&mut self, d: u8, pushed: bool) {
        self.history[self.history_head] = d | (pushed as u8) << 2;
        self.history_head = (self.history_head + 1) % HISTORY;
        self.history_len = (self.history_len + 1).min(HISTORY);
    }

    fn undo(&mut self) {
        if self.history_len == 0 {
            return;
        }
        self.history_head = (self.history_head + HISTORY - 1) % HISTORY;
        self.history_len -= 1;
        let m = self.history[self.history_head];
        self.level.undo(m & 3, m & 4 != 0);
    }

    fn win(&mut self) {
        let (boxes, _, _) = level_params(self.level_num);
        self.session_levels += 1;
        self.session_coins += 1 + boxes as i32;
        self.state = State::Win;
        self.timer = 0.0;
        self.popup.set_text(t!("Boxed in!"), false, true);
    }

    fn handle_menu(&mut self, ctx: &mut GameContext, buttons: &mut Buttons) {
        match self.options_menu.handle_input(buttons, false) {
            MenuResult::Continue => {}
            MenuResult::Closed => self.menu_active = false,
            MenuResult::Action(action) => {
                self.menu_active = false;
                match action {
                    BoxedInAction::Retry => self.retry(),
                    BoxedInAction::NewBoard => self.new_board(ctx),
                }
            }
        }
    }

    fn draw_board(&self, r: &mut Renderer) {
        let lv = &self.level;
        let opts = SpriteOpts::default();
        // Dirt goes down first: the cat and boxes cover what's under them.
        for &(x, y) in &self.scenery.dirt {
            r.draw_pixel(Point::new(x as i32, y as i32), true);
        }
        for &(x, y, v) in &self.scenery.grass {
            r.draw_sprite(
                GRASS_SPRITES[v as usize],
                Point::new(x as i32, y as i32),
                SpriteOpts { transparent: true, ..opts },
            );
        }
        for i in 0..CELLS {
            let pos = Point::new(
                self.origin.x + (i % COLS) as i32 * PITCH,
                self.origin.y + (i / COLS) as i32 * PITCH,
            );
            if lv.wall[i] {
                if lv.visible_wall(i) {
                    // Hollow blocks with a 1px gap, like Sleeping Dogs' hidden tiles.
                    r.draw_rect(pos, Size::new(CELL_IN, CELL_IN), false);
                }
            } else if lv.boxes[i] {
                let sprite = if lv.target[i] { BOX_ON_TARGET } else { BOX };
                r.draw_sprite_raw(sprite, 7, 7, pos, opts);
            } else if i == lv.player {
                r.draw_sprite_raw(CAT, 7, 7, pos, opts);
            } else if lv.target[i] {
                r.draw_sprite_raw(TARGET, 7, 7, pos, opts);
            }
        }
    }
}

impl Scene for BoxedInScene {
    fn enter(&mut self, ctx: &mut GameContext) {
        self.session_levels = 0;
        self.session_coins = 0;
        self.menu_active = false;
        self.level_num = 1;
        self.new_board(ctx);
    }

    fn exit(&mut self, ctx: &mut GameContext) {
        if self.session_levels == 0 {
            return;
        }
        let scale = (self.session_levels as f32 / 5.0).sqrt();
        ctx.apply_stat_changes(&[
            (StatId::Intelligence, 5.0 * scale),
            (StatId::Focus,        5.0 * scale),
            (StatId::Loyalty,      0.5 * scale),
        ]);
        if self.session_coins > 0 {
            ctx.coins += self.session_coins;
        }
    }

    fn update(
        &mut self,
        ctx: &mut GameContext,
        buttons: &mut Buttons,
        dt: f32,
    ) -> Option<SceneId> {
        if buttons.was_just_pressed(Button::Menu1) {
            return Some(SceneId::Menu);
        }

        if self.menu_active {
            self.handle_menu(ctx, buttons);
            return None;
        }

        match self.state {
            State::Win => {
                self.timer += dt;
                if buttons.was_just_pressed(Button::A) || self.timer >= WIN_RESET_DELAY {
                    self.level_num += 1;
                    self.new_board(ctx);
                }
                return None;
            }
            State::Intro => {
                self.timer += dt;
                // A d-pad press dismisses the banner and moves straight away.
                let dpad = [Button::Up, Button::Down, Button::Left, Button::Right]
                    .iter()
                    .any(|&b| buttons.was_just_pressed(b));
                if self.timer >= INTRO_TIME || buttons.was_just_pressed(Button::A) {
                    self.state = State::Playing;
                    return None;
                }
                if !dpad {
                    return None;
                }
                self.state = State::Playing;
            }
            State::Playing => {}
        }

        if buttons.was_just_pressed(Button::Menu2) {
            self.menu_active = true;
            self.options_menu.reset_to(OPTIONS_ITEMS);
            return None;
        }

        if buttons.was_just_pressed(Button::B) {
            self.undo();
            return None;
        }

        let dir = if buttons.was_just_pressed(Button::Up) {
            Some(UP)
        } else if buttons.was_just_pressed(Button::Down) {
            Some(DOWN)
        } else if buttons.was_just_pressed(Button::Left) {
            Some(LEFT)
        } else if buttons.was_just_pressed(Button::Right) {
            Some(RIGHT)
        } else {
            None
        };
        if let Some(d) = dir {
            if let Some(pushed) = self.level.try_move(d) {
                self.record(d, pushed);
                if pushed && self.level.solved() {
                    self.win();
                }
            }
        }

        None
    }

    fn draw(&self, _ctx: &GameContext, renderer: &mut Renderer, _dt_ms: u64) {
        if self.menu_active {
            self.options_menu.draw(renderer);
            return;
        }

        self.draw_board(renderer);

        match self.state {
            State::Intro => self.intro_popup.draw(renderer, false),
            State::Win => self.popup.draw(renderer, false),
            State::Playing => {}
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn generated_levels_solve_by_replaying_the_pulls_as_pushes() {
        for level_num in 1..=20u32 {
            for seed in 1..40u32 {
                let mut rng = seed * 7919 + level_num;
                let (mut level, pulls) = generate(level_num, &mut rng);
                let boxes = level.boxes.iter().filter(|&&b| b).count();
                assert!(boxes >= 1);
                assert!(boxes <= level_params(level_num).0);
                assert!(
                    (0..CELLS).all(|i| !(level.boxes[i] && level.target[i])),
                    "level {} seed {}: a box starts on a target", level_num, seed
                );
                for &(p, d) in pulls.iter().rev() {
                    let stand = step(p as usize, d).unwrap();
                    let path = walk(&level, level.player, stand, &[false; CELLS])
                        .unwrap_or_else(|| panic!("level {} seed {}: can't reach push", level_num, seed));
                    for m in path {
                        assert_eq!(level.try_move(m), Some(false));
                    }
                    assert_eq!(level.try_move(opposite(d)), Some(true));
                }
                assert!(level.solved(), "level {} seed {}", level_num, seed);
            }
        }
    }
}





